//! 📔️ Actual original registry shell admission, source return and one finite caller through close.
use neural_engine::{Registry,Schema,SharedRegistryIssuer,RegistryRetirement,RegistryLeaseRetirement};
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation,OriginalTurnFailure};
use semio_framework_value::{RetainedCloneGrant as Grant,RetainedCloneProgress as Progress,RetirementDemand};
use semio_framework_value::retirement::controlled::ControlledRetirement;
#[global_allocator]
static HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn observe<T>(run:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,(heap.requested_bytes,heap.released_bytes))}
fn clock()->Option<u64>{Some(1000)}
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap()}
fn stock(law:&serde_json::Value)->Grant{let stock=&law["stock"];Grant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:stock["release"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize}}
fn original_caller(law:&serde_json::Value)->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(945),Generation(32),stock(law),clock,law["deadline"].as_u64().unwrap(),law["fuel"].as_u64().unwrap())}
fn input()->Registry{let mut source=Registry::new();source.register_schema(Schema{id:"original".into(),..Default::default()});source}
fn pointer(source:&Registry)->usize{source.schema("original").unwrap().id.as_ptr()as usize}
fn fits(demand:RetirementDemand,grant:Grant)->bool{grant.maximum_items!=0&&grant.maximum_copy_bytes>=demand.copy_bytes&&grant.maximum_capacity_bytes>=demand.capacity_bytes&&grant.maximum_release_bytes>=demand.release_bytes&&grant.maximum_depth>=demand.depth.max(1)}
fn close_payload(source:Registry,caller:&mut OriginalJobFixtureCaller,policy:Grant){let mut owner=ControlledRetirement::new(source).ok().unwrap();for _ in 0..10000{if owner.terminal_is_empty(){let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));return}let(result,heap)=observe(||caller.turn(policy,|cx|{let grant=cx.retained_grant();if cx.should_yield()||!fits(owner.selected_demand(grant.maximum_copy_bytes)?,grant){return Ok(Progress::default())}cx.consume_fuel(1);let progress=owner.step(grant).map_err(|error|OriginalTurnFailure::debit_original(error.with_retained_progress(owner.step_progress()),cx))?.progress();cx.consume_retained(progress)?;Ok(progress)}));let progress=result.unwrap();assert_eq!(progress,caller.receipt());assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));assert_ne!(progress,Progress::default())}panic!("original registry payload did not close")}
fn close_authority(authority:&mut RegistryRetirement,caller:&mut OriginalJobFixtureCaller,policy:Grant){for _ in 0..10000{if authority.terminal_is_empty(){return}let(result,heap)=observe(||caller.turn(policy,|cx|{let grant=cx.retained_grant();let demand=RetirementDemand{copy_bytes:authority.next_copy_byte_demand()?,capacity_bytes:authority.next_capacity_byte_demand(grant.maximum_copy_bytes)?,release_bytes:authority.next_release_byte_demand()?,depth:authority.next_depth_demand()?};if cx.should_yield()||!fits(demand,grant){return Ok(Progress::default())}cx.consume_fuel(1);let progress=authority.close_step(grant).map_err(|error|OriginalTurnFailure::debit_original(error,cx))?.progress();cx.consume_retained(progress)?;Ok(progress)}));let progress=result.unwrap();assert_eq!(progress,caller.receipt());assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));assert_ne!(progress,Progress::default())}panic!("original registry authority did not close")}
fn close_reader(reader:&mut RegistryLeaseRetirement,caller:&mut OriginalJobFixtureCaller,policy:Grant){let(result,heap)=observe(||caller.turn(policy,|cx|{let grant=cx.retained_grant();assert!(grant.maximum_items>0&&grant.maximum_depth>0);cx.consume_fuel(1);let progress=reader.close_step(grant).map_err(|error|OriginalTurnFailure::debit_original(error,cx))?.progress();cx.consume_retained(progress)?;Ok(progress)}));let progress=result.unwrap();assert_eq!(progress,caller.receipt());assert_eq!(heap,(0,0));assert!(reader.terminal_is_empty())}

#[test]
fn original_registry_issuer_reserves_two_shells_before_same_source_donation(){
 let law=fixture();for body in law["copyGrants"].as_array().unwrap(){let policy=Grant{maximum_items:1,maximum_copy_bytes:body.as_u64().unwrap()as usize,..stock(&law)};let mut caller=original_caller(&law);let(source,input_heap)=observe(||input());let mut source=Some(source);let original=pointer(source.as_ref().unwrap());let mut issuer=SharedRegistryIssuer::new();let mut ready=None;let mut shells=0;let mut recipient=0;let mut source_id=0;
  for phase in 0..law["phases"].as_array().unwrap().len(){let demand=issuer.next_demand(policy.maximum_copy_bytes).unwrap();let mut denials=vec![Grant{maximum_items:0,..policy},Grant{maximum_depth:0,..policy}];if demand.capacity_bytes!=0{denials.push(Grant{maximum_capacity_bytes:demand.capacity_bytes-1,..policy})}
   for denied in denials{let before=caller.cumulative_receipt();let fuel=caller.fuel_remaining();let(result,heap)=observe(||caller.turn(denied,|cx|issuer.step(&mut source,cx)));assert!(result.unwrap().ready.is_none());assert_eq!(heap,(0,0));assert_eq!(issuer.phase(),phase as u8);assert_eq!(caller.cumulative_receipt(),before);assert_eq!(caller.fuel_remaining(),fuel);if phase<=3{assert_eq!(pointer(source.as_ref().unwrap()),original)}}
   for (fuel,deadline) in [(0,1000000),(1,1000)]{let before=caller.cumulative_receipt();let remaining=caller.fuel_remaining();let(result,heap)=observe(||caller.turn(policy,|cx|{let mut ready=None;cx.with_original_work_loan(fuel,deadline,|same|{ready=issuer.step(&mut source,same)?.ready;Ok(())})?;Ok(ready)}));assert!(result.unwrap().is_none());assert_eq!(heap,(0,0));assert_eq!(caller.cumulative_receipt(),before);assert_eq!(caller.fuel_remaining(),remaining);assert_eq!(issuer.phase(),phase as u8)}
   let(result,heap)=observe(||caller.turn(policy,|cx|{if recipient==0{recipient=cx.original_recipient_identity();source_id=cx.original_source_parent()?.source_identity()?}assert_eq!(cx.original_recipient_identity(),recipient);assert_eq!(cx.original_source_parent()?.source_identity()?,source_id);issuer.step(&mut source,cx)}));let step=result.unwrap();assert_eq!(step.progress,caller.receipt());assert_eq!(heap,(step.progress.retained_capacity_bytes,step.progress.released_bytes));assert_eq!(heap.0,demand.capacity_bytes);if heap.0!=0{shells+=1}if phase<3{assert_eq!(pointer(source.as_ref().unwrap()),original)}else{assert!(source.is_none())}if step.ready.is_some(){ready=step.ready}
  }
  assert_eq!(shells,law["rootShells"].as_u64().unwrap());assert!(issuer.terminal_is_empty());let(reader,mut authority)=ready.unwrap();assert_eq!(pointer(&reader),original);let mut reader=reader.into_retirement();close_reader(&mut reader,&mut caller,policy);close_authority(&mut authority,&mut caller,policy);let(_,heap)=observe(||{drop(reader);drop(authority);drop(issuer)});assert_eq!(heap,(0,0));let before=caller.cumulative_receipt();let roots=caller.born_bytes();let(released,heap)=observe(||caller.retire(policy));assert_eq!(heap,(0,released));assert_eq!(released,roots);assert_eq!(before.retained_capacity_bytes+input_heap.0,before.released_bytes+input_heap.1+roots);
 }
 println!("[DEBUG] actual original registry2 Arc shells funded before owned source transfer, metadata/capacity/depth and genuine zero-work/expired denials System0, same source ID/recipient/schema pointer, exact five-axis conservation and Drop0 under copy1/3/64")
}

#[test]
fn original_registry_issuer_cancellation_returns_same_payload_after_born_shell_close(){
 let law=fixture();for body in law["copyGrants"].as_array().unwrap(){for stop in law["cancelStops"].as_array().unwrap(){let policy=Grant{maximum_items:1,maximum_copy_bytes:body.as_u64().unwrap()as usize,..stock(&law)};let mut caller=original_caller(&law);let(input,input_heap)=observe(||input());let mut source=Some(input);let original=pointer(source.as_ref().unwrap());let mut issuer=SharedRegistryIssuer::new();
   for _ in 0..stop.as_u64().unwrap(){let(result,heap)=observe(||caller.turn(policy,|cx|issuer.step(&mut source,cx)));let step=result.unwrap();assert!(step.ready.is_none());assert_eq!(heap,(step.progress.retained_capacity_bytes,step.progress.released_bytes))}
   semio_framework_async::poll::resolve_ready(caller.cancel().cancel());issuer.begin_close();let phase=issuer.phase();for _ in 0..10000{if issuer.terminal_is_empty(){break}let demand=issuer.next_demand(policy.maximum_copy_bytes).unwrap();let mut denials=vec![Grant{maximum_items:0,..policy},Grant{maximum_depth:0,..policy}];if demand.release_bytes!=0{denials.push(Grant{maximum_release_bytes:demand.release_bytes-1,..policy})}for denied in denials{let before=caller.cumulative_receipt();let fuel=caller.fuel_remaining();let(result,heap)=observe(||caller.turn(denied,|cx|issuer.close_step(&mut source,cx)));assert_eq!(result.unwrap().progress(),Progress::default());assert_eq!(heap,(0,0));assert_eq!(caller.cumulative_receipt(),before);assert_eq!(caller.fuel_remaining(),fuel)}let(result,heap)=observe(||caller.turn(policy,|cx|issuer.close_step(&mut source,cx)));let progress=result.unwrap().progress();assert_eq!(progress,caller.receipt());assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));assert_ne!(progress,Progress::default());assert_eq!(issuer.phase(),phase)}
   assert!(issuer.terminal_is_empty());assert_eq!(pointer(source.as_ref().unwrap()),original);close_payload(source.take().unwrap(),&mut caller,policy);let(_,heap)=observe(||{drop(source);drop(issuer)});assert_eq!(heap,(0,0));let before=caller.cumulative_receipt();let roots=caller.born_bytes();let(released,heap)=observe(||caller.retire(policy));assert_eq!(heap,(0,released));assert_eq!(released,roots);assert_eq!(before.retained_capacity_bytes+input_heap.0,before.released_bytes+input_heap.1+roots);
  }}
 println!("[DEBUG] actual original registry at every canceled0..5 constructor prefix under copy1/3/64 returns SAME native schema allocation after only born shells close; full conservation and zero implicit Drop release")
}
